  "getReferenceChecks": "query getReferenceChecks($locale: Locale!) {\n  viewer {\n    _id\n    referenceChecks {\n      id\n      references {\n        relationshipText(locale: $locale)\n        organisationName\n        refereeFullName\n        refereeRoleTitle\n        candidateRoleTitle\n        fromDate {\n          shortAbsoluteLabel(locale: $locale)\n        }\n        toDate {\n          shortAbsoluteLabel(locale: $locale)\n        }\n        referenceDate {\n          shortAbsoluteLabel(locale: $locale)\n        }\n      }\n    }\n  }\n}",
