  "GetPersonalDetails": "query GetPersonalDetails($languageCode: LanguageCodeIso!, $countryCode: CountryCodeIso2!, $zone: Zone!) {\n  viewer {\n    _id\n    emailAddress\n    trackingId\n    personalDetails(countryCode: $countryCode, languageCode: $languageCode) {\n      firstName\n      lastName\n      phoneNumber\n      countryCallingCode {\n        id\n        countryCallingCode\n      }\n      defaultCountryCallingCode {\n        id\n        countryCallingCode\n      }\n    }\n    currentLocation2(languageCode: $languageCode, zone: $zone) {\n      id\n      description\n      shortDescription\n      kind\n      countryCode\n    }\n    verifiedIdentity(\n      zone: $zone\n      languageCode: $languageCode\n      platform: WEB\n      source: PROFILE\n    ) {\n      name\n      verificationUrl\n      manageVerificationUrl\n    }\n  }\n}",
