  "GetCTPPreference": "query GetCTPPreference($locale: Locale!, $onlyProductionOption: Boolean!, $zone: Zone!) {\n  viewer {\n    notificationCTPPreferenceGroups(\n      zone: $zone\n      onlyProductionOption: $onlyProductionOption\n    ) {\n      category {\n        description(locale: $locale)\n        id\n        label(locale: $locale, zone: $zone)\n      }\n      preferences {\n        product {\n          description(locale: $locale, zone: $zone)\n          id\n          label(locale: $locale)\n          action {\n            label(locale: $locale, zone: $zone)\n            path\n          }\n        }\n        subscriptions {\n          channel {\n            label(locale: $locale)\n            id\n          }\n          frequency {\n            value\n            options {\n              id\n              label(locale: $locale)\n              description(locale: $locale)\n            }\n          }\n          id\n          subscribed\n          token\n        }\n      }\n    }\n  }\n}",
